import type { MDXContent } from "mdx/types";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { PromptHeading } from "@/components/prompt-heading";
import { caseStudies, findCaseStudy, site } from "@/content";
import type { CSSVars } from "@/lib/css";

// Builds one page per case study at build time.
export function generateStaticParams() {
  return caseStudies.map((project) => ({ slug: project.slug }));
}

// PageProps<"/projects/[slug]"> is generated by Next.js from the folder name. Its `params` is a
// Promise (in Next 16, params arrive asynchronously), so it has to be awaited.
export async function generateMetadata({
  params,
}: PageProps<"/projects/[slug]">): Promise<Metadata> {
  const { slug } = await params;
  return { title: findCaseStudy(slug)?.title };
}

export default async function CaseStudyPage({
  params,
}: PageProps<"/projects/[slug]">) {
  const { slug } = await params;
  const project = findCaseStudy(slug);
  // Unknown slug: show the 404 page. notFound() stops rendering, so `project` is defined below.
  if (!project) notFound();

  // Each case study's body lives in src/content/projects/<slug>.mdx. TypeScript can't know which
  // file a template-string import loads, so it would type it `any`; the annotation fixes that.
  const { default: Body }: { default: MDXContent } = await import(
    `@/content/projects/${slug}.mdx`
  );
  const { path, backLabel } = site.pages.projects;
  const command = `cat ${slug}.md`;
  const style: CSSVars = { "--chars": command.length };

  return (
    <div style={style}>
      <Link
        href="/projects"
        className="inline-block py-2 text-sm text-muted hover:text-teal"
      >
        <span aria-hidden="true">← </span>
        {backLabel}
      </Link>
      <div className="mt-4">
        <PromptHeading path={`${path}/${slug}`} command={command} />
      </div>
      <article className="motion-safe:animate-reveal">
        <p className="mt-8 text-2xl font-bold sm:text-3xl">{project.title}</p>
        <p className="mt-2 text-sm text-muted">{project.stack.join(" · ")}</p>
        <Body />
      </article>
    </div>
  );
}
